package com.specbar2005;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SpecBar2005Plugin.CONFIG_GROUP)
public interface SpecBar2005Config extends Config
{
	@ConfigItem(
		keyName = "showPercentage",
		name = "Show percentage",
		description = "Append the current special attack percentage to the bar text",
		position = 0
	)
	default boolean showPercentage()
	{
		return false;
	}
}

package com.specbar2005;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

public class SpecBar2005Overlay extends Overlay
{
	// Sprites extracted from the 2005-era interface: the empty frame is drawn
	// nine-slice with its transparent hole mapped to the fill area. The dark
	// hatched 0% strip fills the whole slot, and the bright 100% strip is drawn
	// over it clipped to the energy percent, as the original client did. The
	// yellow label sprite is the spec-armed state.
	private static final int SRC_W = 162, SRC_H = 24;
	private static final int SRC_IX = 6, SRC_IY = 6, SRC_IW = 150, SRC_IH = 12;
	private static final int STRIP_W = 150, STRIP_H = 12;
	private static final int LABEL_W = 116, LABEL_H = 8;

	private static final Color BEVEL_LIGHT = new Color(0x50, 0x4B, 0x43);
	private static final Color BEVEL_DARK = new Color(0x1B, 0x1B, 0x18);
	private static final Color BEVEL_SIDE = new Color(0x45, 0x43, 0x3E);
	private static final Color LABEL_ACTIVE = new Color(0xF6, 0xFF, 0x00);

	// Fallback fill bands if the sprites fail to load
	private static final Color[] BANDS = {
		new Color(0xB0, 0x24, 0x15),
		new Color(0xA6, 0x48, 0x15),
		new Color(0x97, 0x5A, 0x10),
		new Color(0x8D, 0x6A, 0x11),
		new Color(0x7F, 0x6F, 0x0E),
		new Color(0x43, 0x47, 0x0E),
		new Color(0x3B, 0x4F, 0x11),
		new Color(0x34, 0x53, 0x10),
		new Color(0x2F, 0x5A, 0x12),
		new Color(0x14, 0x60, 0x15),
	};

	// Fraction of the interior width the letter-spaced label spans
	private static final double LABEL_SPAN = 0.72;

	private final Client client;
	private final SpecBar2005Config config;
	private final BufferedImage frame;
	private final BufferedImage fill;
	private final BufferedImage empty;
	private final BufferedImage label;

	// Pixels from the label's visual center down to the baseline, measured once
	// from the caps glyph bounds (line-box centering pushes caps text too high)
	private int baselineOffset = -1;

	@Inject
	SpecBar2005Overlay(Client client, SpecBar2005Config config)
	{
		this(client, config,
			ImageUtil.loadImageResource(SpecBar2005Overlay.class, "specbar_frame.png"),
			ImageUtil.loadImageResource(SpecBar2005Overlay.class, "specbar_fill.png"),
			ImageUtil.loadImageResource(SpecBar2005Overlay.class, "specbar_empty.png"),
			ImageUtil.loadImageResource(SpecBar2005Overlay.class, "specbar_label.png"));
	}

	// Package-private seam so tests can exercise the no-sprite fallback paths
	SpecBar2005Overlay(Client client, SpecBar2005Config config,
		BufferedImage frame, BufferedImage fill, BufferedImage empty, BufferedImage label)
	{
		this.client = client;
		this.config = config;
		this.frame = frame;
		this.fill = fill;
		this.empty = empty;
		this.label = label;
		setPosition(OverlayPosition.DYNAMIC);
		// Draw right after the combat interface rather than above all widgets,
		// so right-click menus and tooltips still render on top of the bar
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.COMBAT_INTERFACE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget bar = client.getWidget(InterfaceID.CombatInterface.SP_ATTACKBAR);
		if (bar == null || bar.isHidden())
		{
			return null;
		}

		Rectangle b = bar.getBounds();
		if (b == null || b.width <= 0 || b.height <= 0)
		{
			return null;
		}

		// The combat interface draws its hover tooltip inside the same interface
		// pass, so anything drawn after the interface covers it. While a tooltip
		// overlaps the bar, stand aside and let the vanilla bar show so the
		// tooltip stays readable on top. TOOLTIP_BUILT is set only while a
		// tooltip is actually displayed — the widget's bounds go stale after it
		// closes, and it isn't set during the pre-tooltip hover delay
		Widget tooltip = client.getWidget(InterfaceID.CombatInterface.TOOLTIP);
		if (tooltip != null && !tooltip.isHidden()
			&& client.getVarcIntValue(VarClientID.TOOLTIP_BUILT) != 0)
		{
			Rectangle tb = tooltip.getBounds();
			Widget universe = client.getWidget(InterfaceID.CombatInterface.UNIVERSE);
			Point mouse = client.getMouseCanvasPosition();
			if (tb != null && tb.intersects(b)
				&& universe != null && mouse != null
				&& universe.getBounds().contains(mouse.getX(), mouse.getY()))
			{
				return null;
			}
		}

		// Interior = the frame sprite's transparent hole, mapped onto the
		// widget bounds. The bevel is rounded once and mirrored on both sides
		// so the left and right borders stay the same thickness at any size;
		// falls back to proportional insets without the sprite
		Rectangle inner;
		if (frame != null)
		{
			int hBevel = Math.round(b.width * SRC_IX / (float) SRC_W);
			int vBevel = Math.round(b.height * SRC_IY / (float) SRC_H);
			inner = new Rectangle(b.x + hBevel, b.y + vBevel,
				b.width - hBevel * 2, b.height - vBevel * 2);
		}
		else
		{
			int vBevel = Math.max(2, Math.round(b.height * 0.22f));
			int hBevel = Math.max(1, Math.round(b.height * 0.11f));
			inner = new Rectangle(b.x + hBevel, b.y + vBevel,
				b.width - hBevel * 2, b.height - vBevel * 2);
		}
		if (inner.width <= 0 || inner.height <= 0)
		{
			return null;
		}

		// Varp 300 holds special attack energy as percent * 10 (0-1000)
		int percent = Math.max(0, Math.min(100, client.getVarpValue(VarPlayerID.SA_ENERGY) / 10));
		boolean specActive = client.getVarpValue(VarPlayerID.SA_ATTACK) == 1;

		Graphics2D g = (Graphics2D) graphics.create();
		Object oldHint = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		try
		{
			int fillEnd = inner.x + inner.width * percent / 100;

			// Background: the dark hatched 0% strip across the whole slot
			if (empty != null)
			{
				g.drawImage(empty,
					inner.x, inner.y, inner.x + inner.width, inner.y + inner.height,
					0, 0, STRIP_W, STRIP_H, null);
			}
			else
			{
				g.setColor(BEVEL_DARK);
				g.fillRect(inner.x, inner.y, inner.width, inner.height);
			}

			// Fill: the bright 100% strip, clipped to the energy percent
			if (fill != null && fillEnd > inner.x)
			{
				Shape oldClip = g.getClip();
				g.clip(new Rectangle(inner.x, inner.y, fillEnd - inner.x, inner.height));
				g.drawImage(fill,
					inner.x, inner.y, inner.x + inner.width, inner.y + inner.height,
					0, 0, STRIP_W, STRIP_H, null);
				g.setClip(oldClip);
			}
			else if (fill == null)
			{
				for (int i = 0; i < BANDS.length; i++)
				{
					int x0 = inner.x + inner.width * i / BANDS.length;
					int x1 = Math.min(fillEnd, inner.x + inner.width * (i + 1) / BANDS.length);
					if (x1 <= x0)
					{
						break;
					}
					g.setColor(BANDS[i]);
					g.fillRect(x0, inner.y, x1 - x0, inner.height);
				}
			}

			drawLabel(g, inner, percent, specActive);
			drawFrame(g, b, inner);
		}
		finally
		{
			if (oldHint == null)
			{
				g.getRenderingHints().remove(RenderingHints.KEY_INTERPOLATION);
			}
			else
			{
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldHint);
			}
			g.dispose();
		}

		return null;
	}

	private void drawLabel(Graphics2D g, Rectangle inner, int percent, boolean specActive)
	{
		// Spec armed: the original client swaps in the yellow label sprite. It's
		// drawn at native size — downscaling it mangles the 1px glyph strokes —
		// with a fall through to drawn text when the interior is too small
		if (specActive && label != null && !config.showPercentage()
			&& inner.width >= LABEL_W && inner.height >= LABEL_H)
		{
			g.drawImage(label,
				inner.x + (inner.width - LABEL_W) / 2,
				inner.y + (inner.height - LABEL_H) / 2, null);
			return;
		}

		String text = config.showPercentage()
			? "SPECIAL ATTACK: " + percent + "%"
			: "SPECIAL ATTACK";

		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(specActive ? LABEL_ACTIVE : Color.BLACK);
		drawSpaced(g, text, inner, inner.y + inner.height / 2 + baselineOffset(g));
	}

	/**
	 * Draws the extracted frame sprite around {@code inner}. The sprite's
	 * transparent hole maps to {@code inner}; each surrounding strip is
	 * stretched independently so the bevel texture keeps its proportions.
	 * Falls back to a drawn bevel if the resource is missing.
	 */
	private void drawFrame(Graphics2D g, Rectangle b, Rectangle inner)
	{
		if (frame == null)
		{
			int vBevel = Math.max(2, Math.round(b.height * 0.22f));
			g.setColor(BEVEL_SIDE);
			g.fillRect(b.x, b.y, b.width, b.height);
			g.setPaint(new GradientPaint(0, b.y, BEVEL_LIGHT, 0, inner.y, BEVEL_DARK));
			g.fillRect(b.x, b.y, b.width, vBevel);
			g.setPaint(new GradientPaint(0, inner.y + inner.height, BEVEL_LIGHT, 0, b.y + b.height, BEVEL_DARK));
			g.fillRect(b.x, inner.y + inner.height, b.width, b.y + b.height - inner.y - inner.height);
			return;
		}

		int[] dxs = {b.x, inner.x, inner.x + inner.width, b.x + b.width};
		int[] dys = {b.y, inner.y, inner.y + inner.height, b.y + b.height};
		int[] sxs = {0, SRC_IX, SRC_IX + SRC_IW, SRC_W};
		int[] sys = {0, SRC_IY, SRC_IY + SRC_IH, SRC_H};

		// Edges and corners of the nine-slice; the transparent center is skipped
		for (int r = 0; r < 3; r++)
		{
			for (int c = 0; c < 3; c++)
			{
				if ((r == 1 && c == 1) || dxs[c] == dxs[c + 1] || dys[r] == dys[r + 1])
				{
					continue;
				}
				g.drawImage(frame,
					dxs[c], dys[r], dxs[c + 1], dys[r + 1],
					sxs[c], sys[r], sxs[c + 1], sys[r + 1], null);
			}
		}
	}

	private int baselineOffset(Graphics2D g)
	{
		if (baselineOffset < 0)
		{
			Rectangle2D vb = g.getFont()
				.createGlyphVector(g.getFontRenderContext(), "SPECIAL ATTACK")
				.getVisualBounds();
			baselineOffset = -(int) Math.round(vb.getCenterY());
		}
		return baselineOffset;
	}

	/**
	 * Draws {@code text} centered in {@code area}, with extra tracking so it
	 * spans {@link #LABEL_SPAN} of the width like the original sprite label.
	 */
	private static void drawSpaced(Graphics2D g, String text, Rectangle area, int baseline)
	{
		FontMetrics fm = g.getFontMetrics();
		int natural = fm.stringWidth(text);
		double tracking = text.length() > 1
			? Math.max(0, (area.width * LABEL_SPAN - natural) / (text.length() - 1))
			: 0;
		double x = area.x + (area.width - (natural + tracking * (text.length() - 1))) / 2;

		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			g.drawString(String.valueOf(c), (int) Math.round(x), baseline);
			x += fm.charWidth(c) + tracking;
		}
	}
}

package com.specbar2005;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Restyles the special attack bar purely by painting over it. The overlay is
 * fully opaque across the bar's bounds, so no vanilla widget is ever hidden,
 * moved, resized, or modified — the game keeps full control of the bar's
 * visibility and click zone.
 */
@PluginDescriptor(
	name = "2005 Special Attack Bar",
	description = "Restyles the special attack bar with a 2005-era look",
	tags = {"special", "attack", "spec", "bar", "2005", "combat", "ui"}
)
public class SpecBar2005Plugin extends Plugin
{
	static final String CONFIG_GROUP = "specbar2005";

	// Color options from the pre-sprite version; no longer read
	static final String[] OBSOLETE_KEYS = {"fillColor", "emptyColor", "borderColor", "textColor"};

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SpecBar2005Overlay overlay;

	@Inject
	private ConfigManager configManager;

	@Override
	protected void startUp()
	{
		for (String key : OBSOLETE_KEYS)
		{
			configManager.unsetConfiguration(CONFIG_GROUP, key);
		}
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	@Provides
	SpecBar2005Config provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpecBar2005Config.class);
	}
}

package com.specbar2005;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.atLeastOnce;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;

public class SpecBar2005OverlayTest
{
	private static final int PAD = 8;
	private static final Rectangle BOUNDS = new Rectangle(31, 17, 162, 24);

	private Client client;
	private Widget bar;
	private SpecBar2005Config config;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		bar = mock(Widget.class);
		config = mock(SpecBar2005Config.class);
		when(client.getWidget(InterfaceID.CombatInterface.SP_ATTACKBAR)).thenReturn(bar);
		when(bar.getBounds()).thenReturn(BOUNDS);
		when(client.getVarpValue(VarPlayerID.SA_ENERGY)).thenReturn(1000);
	}

	private SpecBar2005Overlay overlay()
	{
		return new SpecBar2005Overlay(client, config);
	}

	private BufferedImage render(SpecBar2005Overlay overlay)
	{
		Rectangle b = bar.getBounds();
		BufferedImage img = new BufferedImage(
			Math.max(1, b.x + Math.max(0, b.width) + PAD * 2),
			Math.max(1, b.y + Math.max(0, b.height) + PAD * 2),
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		assertNull(overlay.render(g));
		g.dispose();
		return img;
	}

	private static int transparentPixels(BufferedImage img, Rectangle area)
	{
		int n = 0;
		for (int y = area.y; y < area.y + area.height; y++)
		{
			for (int x = area.x; x < area.x + area.width; x++)
			{
				if ((img.getRGB(x, y) >>> 24) != 0xFF)
				{
					n++;
				}
			}
		}
		return n;
	}

	private static int paintedOutside(BufferedImage img, Rectangle area)
	{
		int n = 0;
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				if (!area.contains(x, y) && (img.getRGB(x, y) >>> 24) != 0)
				{
					n++;
				}
			}
		}
		return n;
	}

	private static int yellowPixels(BufferedImage img, Rectangle area)
	{
		int n = 0;
		for (int y = area.y; y < area.y + area.height; y++)
		{
			for (int x = area.x; x < area.x + area.width; x++)
			{
				int rgb = img.getRGB(x, y);
				if (((rgb >> 16) & 0xFF) > 200 && ((rgb >> 8) & 0xFF) > 200 && (rgb & 0xFF) < 80)
				{
					n++;
				}
			}
		}
		return n;
	}

	@Test
	public void drawsNothingWhenBarWidgetMissing()
	{
		when(client.getWidget(InterfaceID.CombatInterface.SP_ATTACKBAR)).thenReturn(null);
		assertEquals(0, paintedOutside(render(overlay()), new Rectangle()));
	}

	@Test
	public void drawsNothingWhenBarHidden()
	{
		when(bar.isHidden()).thenReturn(true);
		assertEquals(0, paintedOutside(render(overlay()), new Rectangle()));
	}

	@Test
	public void drawsNothingForEmptyBounds()
	{
		when(bar.getBounds()).thenReturn(new Rectangle(10, 10, 0, 0));
		BufferedImage img = render(overlay());
		assertEquals(0, paintedOutside(img, new Rectangle(10, 10, 0, 0)));
	}

	/**
	 * The plugin never hides the vanilla widgets — the overlay staying fully
	 * opaque over the bar's bounds is what conceals them, so this is a
	 * regression test for that guarantee at a range of widget sizes, fill
	 * levels, and armed states.
	 */
	@Test
	public void coversEveryBarPixelOpaquely()
	{
		int[][] sizes = {{162, 24}, {150, 22}, {145, 21}, {149, 25}, {190, 26}, {120, 16}, {300, 40}};
		for (int[] s : sizes)
		{
			Rectangle bounds = new Rectangle(11, 13, s[0], s[1]);
			when(bar.getBounds()).thenReturn(bounds);
			for (int energy : new int[]{0, 333, 550, 1000})
			{
				for (int armed = 0; armed <= 1; armed++)
				{
					when(client.getVarpValue(VarPlayerID.SA_ENERGY)).thenReturn(energy);
					when(client.getVarpValue(VarPlayerID.SA_ATTACK)).thenReturn(armed);
					BufferedImage img = render(overlay());
					assertEquals("transparent pixels at " + s[0] + "x" + s[1]
							+ " energy=" + energy + " armed=" + armed,
						0, transparentPixels(img, bounds));
					assertEquals("painted outside bounds at " + s[0] + "x" + s[1],
						0, paintedOutside(img, bounds));
				}
			}
		}
		when(bar.getBounds()).thenReturn(BOUNDS);
	}

	/**
	 * If the sprite resources ever fail to load, the drawn fallback must still
	 * fully cover the vanilla bar.
	 */
	@Test
	public void fallbackDrawingAlsoCoversFully()
	{
		SpecBar2005Overlay noSprites = new SpecBar2005Overlay(client, config, null, null, null, null);
		for (int energy : new int[]{0, 550, 1000})
		{
			when(client.getVarpValue(VarPlayerID.SA_ENERGY)).thenReturn(energy);
			BufferedImage img = render(noSprites);
			assertEquals(0, transparentPixels(img, BOUNDS));
			assertEquals(0, paintedOutside(img, BOUNDS));
		}
	}

	@Test
	public void readsEnergyFromSaEnergyVarp()
	{
		render(overlay());
		verify(client, atLeastOnce()).getVarpValue(VarPlayerID.SA_ENERGY);
	}

	@Test
	public void fillClipsAtEnergyPercent()
	{
		Rectangle inner = new Rectangle(BOUNDS.x + 6, BOUNDS.y + 6, 150, 12);
		int quarter = inner.x + inner.width / 4;
		int threeQuarter = inner.x + inner.width * 3 / 4;
		int midY = inner.y + 1; // top rows avoid the label

		when(client.getVarpValue(VarPlayerID.SA_ENERGY)).thenReturn(1000);
		BufferedImage full = render(overlay());
		when(client.getVarpValue(VarPlayerID.SA_ENERGY)).thenReturn(500);
		BufferedImage half = render(overlay());

		// Inside the filled half the two renders match; past the clip point
		// the half-full bar shows the dark empty strip instead of bright fill
		assertEquals(full.getRGB(quarter, midY), half.getRGB(quarter, midY));
		assertNotEquals(full.getRGB(threeQuarter, midY), half.getRGB(threeQuarter, midY));

		// The ramp runs red on the left to green on the right
		int left = full.getRGB(quarter, midY);
		int right = full.getRGB(threeQuarter, midY);
		assertTrue(((left >> 16) & 0xFF) > ((left >> 8) & 0xFF));
		assertTrue(((right >> 8) & 0xFF) > ((right >> 16) & 0xFF));
	}

	@Test
	public void emptyEnergyShowsNoBrightFill()
	{
		when(client.getVarpValue(VarPlayerID.SA_ENERGY)).thenReturn(0);
		BufferedImage zero = render(overlay());
		when(client.getVarpValue(VarPlayerID.SA_ENERGY)).thenReturn(1000);
		BufferedImage full = render(overlay());
		// The filled left edge at 100% is bright red; at 0% it must differ
		assertNotEquals(full.getRGB(BOUNDS.x + 8, BOUNDS.y + 7), zero.getRGB(BOUNDS.x + 8, BOUNDS.y + 7));
	}

	@Test
	public void armedSpecShowsYellowLabelSprite()
	{
		Rectangle inner = new Rectangle(BOUNDS.x + 6, BOUNDS.y + 6, 150, 12);
		assertEquals(0, yellowPixels(render(overlay()), inner));

		when(client.getVarpValue(VarPlayerID.SA_ATTACK)).thenReturn(1);
		assertTrue(yellowPixels(render(overlay()), inner) > 0);
	}

	@Test
	public void armedSpecOnSmallWidgetFallsBackToText()
	{
		// 120px widget → ~111px interior, narrower than the 116px label sprite;
		// downscaling it would mangle the glyphs, so yellow text is drawn instead
		when(bar.getBounds()).thenReturn(new Rectangle(9, 9, 120, 16));
		Rectangle inner = new Rectangle(9 + 5, 9 + 4, 111, 8);
		when(client.getVarpValue(VarPlayerID.SA_ATTACK)).thenReturn(1);
		assertTrue(yellowPixels(render(overlay()), inner) > 0);
	}

	@Test
	public void armedSpecWithPercentageUsesYellowText()
	{
		when(config.showPercentage()).thenReturn(true);
		Rectangle inner = new Rectangle(BOUNDS.x + 6, BOUNDS.y + 6, 150, 12);

