	private static int saturation(int rgb)
	{
		int r = (rgb >> 16) & 0xFF, g = (rgb >> 8) & 0xFF, b = rgb & 0xFF;
		return Math.max(r, Math.max(g, b)) - Math.min(r, Math.min(g, b));
	}

	@Test
	public void leftAndRightBezelsAreSymmetric()
	{
		// 150px widget: rounding the interior mapping independently produced a
		// 6px left bezel but a 5px right one; both must come out equal
		when(bar.getBounds()).thenReturn(new Rectangle(9, 9, 150, 24));
		BufferedImage img = render(overlay());
		int y = 9 + 8; // inside the interior, above the label
		assertTrue("left interior is saturated fill", saturation(img.getRGB(9 + 6, y)) > 50);
		assertTrue("left edge column is bezel", saturation(img.getRGB(9 + 5, y)) < 50);
		assertTrue("right interior is saturated fill", saturation(img.getRGB(9 + 143, y)) > 50);
		assertTrue("right edge column is bezel", saturation(img.getRGB(9 + 144, y)) < 50);
	}

