package com.specbar2005;

import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Before;
import org.junit.Test;

public class SpecBar2005PluginLifecycleTest
{
	private OverlayManager overlayManager;
	private ConfigManager configManager;
	private SpecBar2005Plugin plugin;

	@Before
	public void setUp()
	{
		overlayManager = mock(OverlayManager.class);
		configManager = mock(ConfigManager.class);
		plugin = Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				bind(Client.class).toInstance(mock(Client.class));
				bind(OverlayManager.class).toInstance(overlayManager);
				bind(ConfigManager.class).toInstance(configManager);
				bind(SpecBar2005Config.class).toInstance(mock(SpecBar2005Config.class));
			}
		}).getInstance(SpecBar2005Plugin.class);
	}

	@Test
	public void startUpAddsAndShutDownRemovesOverlay()
	{
		plugin.startUp();
		verify(overlayManager).add(any(SpecBar2005Overlay.class));

		plugin.shutDown();
		verify(overlayManager).remove(any(SpecBar2005Overlay.class));
	}

	@Test
	public void startUpClearsObsoleteColorKeys()
	{
		plugin.startUp();
		for (String key : new String[]{"fillColor", "emptyColor", "borderColor", "textColor"})
		{
			verify(configManager).unsetConfiguration("specbar2005", key);
		}
	}

	@Test
	public void startUpKeepsCurrentSettings()
	{
		plugin.startUp();
		verify(configManager, never()).unsetConfiguration(eq("specbar2005"), eq("showPercentage"));
	}

	@Test
	public void providesConfigFromConfigManager()
	{
		SpecBar2005Config config = mock(SpecBar2005Config.class);
		when(configManager.getConfig(SpecBar2005Config.class)).thenReturn(config);
		assertSame(config, plugin.provideConfig(configManager));
	}
}

